/* Uses a separate MiniChess state; no game progress, room, socket or storage access. */
(() => {
  'use strict';
  const M=MiniChess,L=MiniLessons,names={K:'킹',R:'룩',B:'비숍',P:'폰',G:'승급 폰'},glyph={K:'♚',R:'♜',B:'♝',P:'♟',G:'♟'},pos=i=>'ABC'[i%3]+(4-Math.floor(i/3));
  const dialog=document.createElement('dialog');dialog.id='mini-picture-practice';dialog.setAttribute('aria-labelledby','mini-practice-title');document.body.appendChild(dialog);
  let step=0,state,selection=null,moved=false,done=false,message='';
  const lesson=()=>L.lessons[step],same=(a,b)=>a.to===b.to&&a.from===b.from&&a.drop===b.drop;
  function reset(){state=L.create(step,M);selection=null;moved=false;done=false;message='';render();}
  function selectedActions(){return selection?M.actions(state).filter(a=>selection.drop?a.drop===selection.drop:a.from===selection.from):[];}
  function piece(pc){return `<span class="piece ${pc.p===0?'blue-piece':'purple-piece'}"><span class="glyph">${glyph[pc.t]}</span><span class="piece-name">${names[pc.t]}</span></span>`;}
  function render(){const p=lesson(),actions=selectedActions();dialog.innerHTML=`<div class="dialog-head"><span>그림으로 배우기 · ${step+1}/${L.lessons.length}</span><button type="button" data-mini-practice-close aria-label="미니 체스 연습 닫기">닫기</button></div><h2 id="mini-practice-title" tabindex="-1">12칸 미니 체스 · 그림 연습</h2><p class="practice-note">시간·횟수 제한 없는 예시 연습입니다. 로컬 진행·이동 기록과 온라인 대전은 바뀌지 않아요.${document.querySelector('#lobby')?' 온라인 경기 중 상대의 차례는 계속 진행됩니다.':''}</p><h3>${p.title}</h3><p>${p.text}</p><p class="mini-practice-legend">블루: 나 · 앞으로 ↑ / 퍼플: 상대 · 앞으로 ↓<br>점선: 연습 목표 · 초록: 이동 가능 · 분홍: 잡기 가능</p><div class="pocket mini-practice-hand" aria-label="연습 블루 보유 말"><b>블루 보유 말</b>${state.hands[0].length?[...new Set(state.hands[0])].map(t=>`<button type="button" class="hand-piece blue-piece ${selection?.drop===t?'chosen':''}" data-mini-practice-drop="${t}" aria-label="연습 ${names[t]} 재투입" ${moved?'disabled':''}>${glyph[t]} ${names[t]} ×${state.hands[0].filter(n=>n===t).length}</button>`).join(''):'<span class="empty-hand">잡은 말이 없습니다</span>'}</div><div class="chess-board mini-practice-board" role="group" aria-label="연습용 3열 4행 체스판">${state.board.map((pc,i)=>{const a=actions.some(a=>a.to===i),target=!moved&&(selection?i===p.action.to:p.action.drop?false:i===p.action.from),chosen=selection?.from===i;return `<button type="button" data-mini-practice-cell="${i}" class="square ${(Math.floor(i/3)+i%3)%2?'alt':''} ${a?(pc?'capture':'target'):''} ${chosen?'chosen':''} ${target?'mini-practice-goal':''}" aria-label="연습 ${pos(i)} ${pc?(pc.p===0?'블루':'퍼플')+' '+names[pc.t]:'빈칸'}${a?' · '+(pc?'잡기 가능':'이동 가능'):''}${target?' · 눌러보세요':''}" ${moved?'disabled':''}><span class="coord">${pos(i)}</span>${pc?piece(pc):a?'·':''}${pc?.t==='G'?'<span class="promotion">승급</span>':''}</button>`;}).join('')}</div>${state.board.some(pc=>pc?.t==='G')?'<div class="mini-promoted-diagram" role="img" aria-label="승급 폰은 위 대각선과 위, 좌우, 뒤로 한 칸. 뒤쪽 대각선은 불가"><span>↖</span><span>↑</span><span>↗</span><span>←</span><span>♟</span><span>→</span><span>×</span><span>↓</span><span>×</span></div>':''}${moved&&p.reply&&!done?'<div class="alert-line">킹 진입! 아직 승리가 아니에요. 상대 한 차례를 확인하세요.</div><button type="button" class="primary" data-mini-practice-reply>상대의 한 수 진행해보기</button>':''}${state.result?`<div class="turn-banner finished" role="status"><strong>${state.result.winner===0?'블루 승리':'퍼플 승리'}</strong><small>${state.result.reason}</small></div>`:''}<p class="light-practice-status" role="status" aria-live="polite">${message||'점선으로 표시된 블루 말이나 보유 말을 눌러 시작해보세요.'}</p><div class="actions practice-actions"><button type="button" data-mini-practice-reset>이 연습 다시 하기</button>${done&&step<L.lessons.length-1?'<button type="button" class="primary" data-mini-practice-next>다음 연습 →</button>':''}</div><button type="button" class="practice-entry light-return" data-mini-practice-close>${done&&step===L.lessons.length-1?'연습 완료 · 대전 화면으로 돌아가기':'대전 화면으로 돌아가기'}</button>`;}
  dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
    if(b.hasAttribute('data-mini-practice-close'))dialog.close();
    else if(b.hasAttribute('data-mini-practice-reset')){reset();dialog.querySelector('h2').focus();}
    else if(b.hasAttribute('data-mini-practice-next')){step++;reset();dialog.querySelector('h2').focus();}
    else if(b.hasAttribute('data-mini-practice-drop')){selection={drop:b.dataset.miniPracticeDrop};message='보유 말도 한 차례를 써서 빈칸에 놓아요. 점선 목표 칸을 눌러보세요.';render();}
    else if(b.hasAttribute('data-mini-practice-reply')){state=M.apply(state,lesson().reply).state;done=true;message=state.result.winner===0?'상대 한 차례 동안 살아남았어요. 끝줄 진입 승리입니다.':'상대가 킹을 잡았어요. 끝줄에 진입했어도 킹 포획이 먼저 판정됩니다.';render();}
    else if(b.hasAttribute('data-mini-practice-cell')){const i=+b.dataset.miniPracticeCell,action=selectedActions().find(a=>a.to===i),p=lesson();if(action&&same(action,p.action)){const out=M.apply(state,action);state=out.state;selection=null;moved=true;done=!p.reply;message=out.event.captured?`${names[out.event.captured]}을 잡았어요! ${out.event.captured==='K'?'킹 포획 즉시 승리입니다.':'내 보유 말로 바뀌어 다음 내 차례에 재투입할 수 있어요.'}`:out.event.promoted?'폰이 승급했어요. 아래 여섯 방향 그림을 확인하세요.':action.drop?'보유 말을 빈칸에 재투입했어요. 보유 말 하나가 줄고 한 차례를 사용했습니다.':p.reply?'킹이 끝줄에 들어갔어요. 지금은 진입 대기 상태예요.':`${names[out.event.moved]} ${pos(action.from)} → ${pos(action.to)} · 한 칸 이동했어요.`;render();return;}if(state.board[i]?.p===0&&!p.action.drop){selection={from:i};message='표시된 이동 가능 칸 중 점선 목표 칸을 눌러보세요.';}else message='이번 예시의 점선 목표를 따라 눌러보세요. 다른 칸에는 이동하지 않았어요.';render();}
  });
  function open(){step=0;reset();dialog.showModal();dialog.querySelector('h2').focus();}
  const button=document.createElement('button');button.type='button';button.className='practice-entry';button.textContent='시간제한 없는 그림 연습';button.addEventListener('click',open);document.querySelector('.mini-title').appendChild(button);
  if(new URLSearchParams(location.search).get('practice')==='1')open();
})();
